#!/usr/bin/env node
// The agent-facing rules live in src/instructions.ts. Fail if any copy drifted:
//   - AGENTS.md and .cursor/rules/agent-undo.mdc are generated by `npm run build` and must match
//     the generator byte for byte;
//   - skills/agent-undo/SKILL.md is hand-written and must carry every CORE_RULE verbatim.
// Reads bin/core-rules.cjs (the committed bundle of src/instructions.ts; check-bundles.js keeps it fresh).
const fs = require('node:fs');
const path = require('node:path');

const root = path.join(__dirname, '..');
const { CORE_RULES, getAgentsMd, getCursorRule } = require(path.join(root, 'bin/core-rules.cjs'));
const read = (rel) => fs.readFileSync(path.join(root, rel), 'utf8').replace(/\r\n/g, '\n');

const problems = [];
for (const [rel, expected] of [['AGENTS.md', getAgentsMd()], ['.cursor/rules/agent-undo.mdc', getCursorRule()]]) {
  if (!fs.existsSync(path.join(root, rel))) problems.push(`${rel} is missing`);
  else if (read(rel) !== expected) problems.push(`${rel} drifted from src/instructions.ts`);
}
const skill = read('skills/agent-undo/SKILL.md');
CORE_RULES.forEach((rule, i) => {
  if (!skill.includes(`${i + 1}. ${rule}`)) problems.push(`skills/agent-undo/SKILL.md: rule ${i + 1} missing or reworded`);
});

if (problems.length) {
  for (const p of problems) console.error(p);
  console.error('Edit src/instructions.ts, run `npm run build`, and copy changed rules into skills/agent-undo/SKILL.md.');
  process.exit(1);
}
console.log(`Rule copies match src/instructions.ts (${CORE_RULES.length} rules in AGENTS.md, Cursor rule, SKILL.md).`);
